import sys, time, hmac, hashlib, json, types

class _Route:
    def __init__(self, path, methods=None): self.path = path
    def __call__(self, fn): routes.append((self.path, fn)); return fn
routes = []
class Flask:
    def __init__(self, name): self.name = name
    def route(self, path, methods=None): return _Route(path, methods)
    def run(self, *a, **k): pass
flask_mod = types.ModuleType('flask')
flask_mod.Flask = Flask; flask_mod.request = None
flask_mod.jsonify = lambda *a, **kw: (a[0] if a else kw)

class SignatureVerificationError(Exception): pass
class Webhook:
    @staticmethod
    def construct_event(payload, sig_header, secret):
        try:
            parts = dict(item.split('=', 1) for item in sig_header.split(','))
            ts, sig = parts['t'], parts['v1']
            expected = hmac.new(secret.encode(), f"{ts}.{payload}".encode(), hashlib.sha256).hexdigest()
            if not hmac.compare_digest(sig, expected):
                raise SignatureVerificationError("Signature mismatch")
        except SignatureVerificationError:
            raise
        except Exception as e:
            raise ValueError(f"Invalid header: {e}")
        return json.loads(payload)
class WebhookSignature:
    @staticmethod
    def generate_header(t, payload, secret):
        sig = hmac.new(secret.encode(), f"{t}.{payload}".encode(), hashlib.sha256).hexdigest()
        return f"t={t},v1={sig}"
class _Event:
    @staticmethod
    def construct_from(obj, key): return obj
class _error: SignatureVerificationError = SignatureVerificationError
stripe_mod = types.ModuleType('stripe')
stripe_mod.Webhook = Webhook; stripe_mod.WebhookSignature = WebhookSignature
stripe_mod.Event = _Event; stripe_mod.error = _error; stripe_mod.api_key = 'sk_test_dummy'
sys.modules['flask'] = flask_mod; sys.modules['stripe'] = stripe_mod

